import{_ as i,l as s,o as a,c as l,v as r,p as o,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"Selinger 动态规划","description":"","frontmatter":{"title":"Selinger 动态规划","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/selinger-dp.md","filePath":"cs/selinger-dp.md","lastUpdated":1789023840000}'),h={name:"cs/selinger-dp.md"};function E(S,e,m,_,D,P){const n=s("Mermaid");return a(),l("div",null,[e[1]||(e[1]=r('<h1 id="selinger-动态规划" tabindex="-1">Selinger 动态规划 <a class="header-anchor" href="#selinger-动态规划" aria-label="Permalink to &quot;Selinger 动态规划&quot;">​</a></h1><div class="epigraph"><p>System R 的优化器按关系子集做动态规划：每个子集保留若干有趣的有序计划，用代价剪掉被支配者。</p><footer>—— 据 Selinger et al., Access Path Selection in a Relational Database Management System, SIGMOD 1979；Ramakrishnan and Gehrke</footer></div><p>依赖理论在 <a href="/cs/5nf-denormalization">5NF 与反规范化</a> 封口。本课打开优化器单元：主干 <a href="/cs/cost-estimate">代价估计</a> 与 <a href="/cs/query-plan">查询计划</a> 已有代价公式与物理树，但连接顺序怎么搜只留下「搜索」。缺口是 Selinger 动态规划（DP）：在左深树（及有趣序）上把指数空间收成 \\(O(3^n)\\) 量级的子集 DP，而不是 \\(n!\\) 穷举。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 表内连接，左深树有 \\(n!\\) 叶排列。每条边还要选算法（NLJ/哈希/归并）与访问路径（堆扫/索引）。穷举不可能。启发式（始终最小表在外）会在倾斜与相关谓词上翻车。缺口是<strong>最优子结构</strong>：一组关系的最优计划，由其真子集的最优计划拼接——若代价可加且无「有趣顺序」问题，标准 DP 即可。</p><p>有趣顺序（interesting order）：若上层排序、归并连接或 <code>GROUP BY</code> 能用到某序，则同一子集要保留多条计划：最便宜无序的、以及各有趣序上最便宜的。被支配（同序更贵）的剪掉。这是 Selinger 相对朴素 DP 的关键补丁。</p><p><span class="marginnote">Selinger et al., SIGMOD 1979，System R。代价用 CPU 与 I/O 加权。本课不把 System R 的实现表当现代优化器的全部，只钉 DP 骨架。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每个非空子集 \\(S\\)，枚举 \\(S = S_1 \\cup \\{R\\}\\)（左深）或更一般的拆分（后课 bushy）。对 \\(S_1\\) 的每个幸存计划与 \\(R\\) 的访问路径，用连接算法生成候选，估基数与代价，按（序、代价）保留 Pareto。单表：索引与堆扫描的代价，谓词选择率来自 <a href="/cs/histogram-card">直方图</a>。</p><p>外连接、半连接限制谁能当「下一张表」；DP 状态仍是子集，合法边更少。本课以内连接为主，点名限制。</p>',10)),(a(),o(c,null,{default:t(()=>[p(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%85%B3%E7%B3%BB%E5%AD%90%E9%9B%86%20S%22%5D%20--%3E%20SUB%5B%22%E7%9C%9F%E5%AD%90%E9%9B%86%E8%AE%A1%E5%88%92%22%5D%0A%20%20SUB%20--%3E%20JOIN%5B%22%E5%8A%A0%E4%B8%80%E5%BC%A0%E8%A1%A8%20%2B%20%E7%AE%97%E5%AD%90%22%5D%0A%20%20JOIN%20--%3E%20INT%5B%22%E6%8C%89%E6%9C%89%E8%B6%A3%E5%BA%8F%E4%BF%9D%E7%95%99%22%5D%0A%20%20INT%20--%3E%20PRUNE%5B%22%E5%89%AA%E6%8E%89%E5%90%8C%E5%BA%8F%E6%9B%B4%E8%B4%B5%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>基数沿树传播：子计划输出行数 × 选择率。估错则 DP 精确优化错误数字——后课误差传播。DP 保证的是：在代价模型与左深限制下最优，不是真实运行时间最优。</p><p>计划缓存可把 DP 结果按语句形状存住；参数窥视改变选择率则应重跑 DP 或用通用计划。这与预编译课衔接，本课不重做缓存。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 bushy 树、延迟笛卡尔积、DPccp 的连通子集枚举写完——下一课连接顺序搜索空间。也不校准代价常数。学习型优化器更后。</p><p>后课默认：多表连接用 DP（或等价动态规划）在有趣序下搜；启发式只是退化。搜索空间形状决定 \\(n\\) 能到几。</p><p>System R 把「访问路径选择」与「连接顺序」放进同一 DP，不是两段无关脚本。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Selinger DP 按子集拼接计划，保留有趣序上的非支配者。</li><li>保证的是模型内最优，不是真实时间最优。</li><li>下一课：左深、右深、bushy 与连通性如何撑开搜索空间。</li><li>出处：Selinger et al., SIGMOD 1979；Ramakrishnan and Gehrke。</li></ul>',9))])}const u=i(h,[["render",E]]);export{B as __pageData,u as default};
